  "summary": [
    "Polls place CDU/Greens ahead of AfD in Baden-Württemberg, with AfD polling in the high teens to low twenties.",
    "Historical base-rate in BW shows AfD has never won the most seats; 2021 result: Greens 32.6% and AfD around 9.7%.",
    "Prediction markets and multiple forecast models do not project AfD as winner; the leading party is CDU or Greens."
  ],
  "confidence": "high",
  "narrative": "Current polling and historical patterns imply an extremely low chance that AfD wins the most seats in BW 2026. While a late swing could theoretically boost AfD, the balance of evidence supports a near-zero probability, with an estimated calibrated probability around 1%.",
  "justification": {
    "anchor": {
      "probability": 0.02,
      "basis": "reference-class forecasts show AfD not leading; anchor around low probability (roughly 2%) based on BW's historical results and current polling signals."
    },
    "factor_updates": [
      {
        "factor": "Poll lead of CDU/Greens vs AfD",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "February 2026 polls show CDU ~28–29%, Greens ~25–27%, AfD ~18–21%, reducing likelihood of AfD having the most seats."
      },
      {
        "factor": "Historical base rate/previous Baden-Württemberg Landtag results",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "Past elections (2021) had AfD at 9.7% with Greens/CDU ahead; historically, AfD has not led BW, anchoring very low odds of plurality."
      },
      {
        "factor": "Prediction-market signals (Polymarket/Grok) about the election",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Markets do not price AfD as winner; support for Greens/CDU remains stronger."
      },
      {
        "factor": "Electoral-system and coalition dynamics in Baden-Württemberg",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "PR framework and coalition patterns in BW favor larger party blocs (Greens/CDU) sustaining majority or plurality against AfD."
      },
      {
        "factor": "Upside risk: potential polling swing to 25%+ for AfD",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "A credible late swing could raise AfD's seats; however, no current indications of such a swing exist in the data."
      }
    ],
    "synthesis_rationale": "The synthesis weights the strong and consistent signals that AfD is unlikely to lead in BW: initial anchor near 2%, downward adjustments from current polls and historical base rates, with only modest upside from a hypothetical late surge. The result is a calibrated probability near 1% with a tight range, acknowledging residual uncertainty."
  }
}

